('op:item:maldicao:Energética','op','livro-basico','maldicao','arma · Energia','Energética',605,'{"tipo": "modificacao", "maldicao": true, "elemento": "Energia", "aplica": ["corpo", "disparo", "fogo", "pesada"], "pag": 146, "desc": "Maldição de Energia. Gaste 2 PE por ataque: a arma (ou a munição) vira Energia pura, dá +5 no ataque, ignora resistência a dano e converte todo o dano em Energia.", "mod": {"catg": 1, "esp": 0, "def": 0}}'::jsonb),
